    opacityEase: "sine.inOut",   // Softer ease-in-ease-out for opacity
    delay: 0,
    blur: 2,                     // Subtle blur
    y: 2,                        // Subtle movement
    cleanup: true
  };

  const settings = { ...defaults, ...options };

  // Skip certain elements
  if (element.classList.contains('no-animate') || 
      element.tagName === 'BUTTON' || 
      element.tagName === 'INPUT') {
    return;
  }

  // Skip if already animated
  if (animatedElements.has(element)) {
    return;
  }

  // Prepare element for animation
  const spans = prepareElementForAnimation(element);
  if (!spans.length) return;

  // Create timeline for this element
  const timeline = gsap.timeline({
    delay: settings.delay,
    onComplete: () => {
      // Add subtle effects to marked characters
      spans.forEach(span => {
        if (span.classList.contains('gsap-char-flicker')) {
          gsap.to(span, {
            opacity: 0.8,
            duration: 0.1,
            repeat: -1,
            yoyo: true,
            ease: "none",
            repeatDelay: getRandomValue(1.5, 3)
          });
        }

        if (span.classList.contains('gsap-char-glow')) {
          const textShadow = "0 0 3px rgba(255, 255, 255, 0.6)";
          gsap.to(span, {
            textShadow,
            duration: 1.5,
            repeat: -1,
            yoyo: true,
            ease: "sine.inOut"
          });
        }
      });
    }
  });

  // Create custom stagger array for more natural typing rhythm
  const staggerArray = [];

  // Build array of custom stagger times for each character
  for (let i = 0; i < spans.length; i++) {
    const char = spans[i].textContent;
    let pause = getTypingPause();

    // Add longer pauses after punctuation
    if (i > 0 && '.?!,:;'.includes(spans[i-1].textContent)) {
      pause = getRandomValue(0.15, 0.3); // 150-300ms pause after punctuation
    }

    staggerArray.push(pause);
  }

  // Animate opacity with a softer ease-in-ease-out separately
  timeline.to(spans, {
    opacity: 1,
    duration: settings.opacityDuration,
    ease: settings.opacityEase, // Softer fade-in
    stagger: {
      each: staggerArray,
      from: "start",
      ease: "none"
    }
  }, 0);

  // Animate position and blur with original timing
  timeline.fromTo(spans, 
    { 
      filter: `blur(${settings.blur}px)`,
      y: settings.y
    },
    { 
      filter: "blur(0px)",
      y: 0,
      duration: settings.duration,
      ease: settings.ease,
      stagger: {
        each: staggerArray,
        from: "start",
        ease: "none"
      }
    }, 
    0
  );

  return timeline;
};

/**
 * Find and animate multiple text elements within a container
 * @param {HTMLElement} container - Container element
 * @param {Object} options - Animation options
 */
export const animateTextInContainer = (container, options = {}) => {
  if (!container) return;

  // Define selectors for elements to animate
  const targetSelectors = [
    'h1, h2, h3, h4, h5, h6',            // Headings
    'p',                                 // Paragraphs
    '.category-item > a',                // Category links
    'li',                                // List items
    '.sub-links a:not(.no-animate)'      // Sub navigation links
  ];

  // Exclude selectors that shouldn't be animated
  const excludeSelectors = options.excludeSelectors || [
    '.alien-title',
    '.no-animate',
    'button',
    'input',
    'textarea',
    '.gsap-animated',  // Skip already animated elements
    '*[class*="gsap-"]'    // Skip any elements with gsap classes
  ];

  // Find all elements to animate
  let elementsToAnimate = [];
  targetSelectors.forEach(selector => {
    const elements = container.querySelectorAll(selector);
    elementsToAnimate = [...elementsToAnimate, ...Array.from(elements)];
  });

  // Filter out excluded elements and already animated elements
  elementsToAnimate = elementsToAnimate.filter(el => {
    // Skip if already animated
    if (animatedElements.has(el)) return false;

    // Skip elements matching exclude selectors
    return !excludeSelectors.some(selector => {
      if (el.matches && el.matches(selector)) return true;
      if (el.closest && el.closest(selector)) return true;
      return false;
    });
  });

  // Create master timeline
  const masterTimeline = gsap.timeline();

  // Sort elements by their vertical position on the page
  elementsToAnimate.sort((a, b) => {
    const rectA = a.getBoundingClientRect();
    const rectB = b.getBoundingClientRect();

    // If elements are on the same line (within a small threshold)
    if (Math.abs(rectA.top - rectB.top) < 5) {
      // Sort by horizontal position for elements on the same line
      return rectA.left - rectB.left;
    }

    // Otherwise sort by vertical position
    return rectA.top - rectB.top;
  });

  // Group elements by line
  const lineGroups = [];
  let currentLineTop = -1;
  let currentLineGroup = [];

  elementsToAnimate.forEach(element => {
    const rect = element.getBoundingClientRect();

    // If this is a new line (with some threshold for line height variations)
    if (currentLineTop === -1 || rect.top > currentLineTop + 5) {
      if (currentLineGroup.length > 0) {
        lineGroups.push(currentLineGroup);
      }
      currentLineGroup = [element];
      currentLineTop = rect.top;
    } else {
      // Same line, add to current group
      currentLineGroup.push(element);
    }
  });

  // Add the last group if it exists
  if (currentLineGroup.length > 0) {
    lineGroups.push(currentLineGroup);
  }

  // Create a sequence function that creates and returns a Promise for animating one line
  const animateLine = (lineElements, lineIndex) => {
    return new Promise(resolve => {
      // Create a timeline for this line
      const lineTimeline = gsap.timeline({
        onComplete: () => resolve()  // Resolve the promise when the line animation completes
      });

      // Animate each element in this line
      lineElements.forEach((element, elementIndex) => {
        // Determine element type to set appropriate timing
        const isHeading = /^H[1-6]$/.test(element.tagName);
        const isParagraph = element.tagName === 'P';

        // Calculate estimated duration based on text length and stagger
        const staggerRange = isHeading ? [0.01, 0.1] : 
                            isParagraph ? [0.01, 0.08] : [0.01, 0.06];

        // Animate this element
        const elementTimeline = animateText(element, {
          ...options,
          delay: elementIndex * 0.05,  // Small delay between elements on same line
          staggerRange: staggerRange
        });

        if (elementTimeline) {
          lineTimeline.add(elementTimeline, 0);  // Add at position 0 (all elements in line start together)
        }
      });

      // Add a small buffer to ensure the line is complete
      lineTimeline.to({}, { duration: 0.1 });
    });
  };

  // Use an async function to animate lines sequentially
  const animateAllLines = async () => {
    for (let i = 0; i < lineGroups.length; i++) {
      await animateLine(lineGroups[i], i);
    }
  };

  // Start the sequential animation
  animateAllLines();

  return masterTimeline;
};

/**
 * Add required CSS for animations
 */
const addAnimationStyles = () => {
  if (document.getElementById('gsap-text-styles')) return;

  const styleEl = document.createElement('style');
  styleEl.id = 'gsap-text-styles';
  styleEl.textContent = `
    .gsap-char {
      display: inline-block;
      transform-origin: center;
      opacity: 0;
      position: relative;
      white-space: pre;
    }

    .gsap-animated {
      position: relative;
    }

    .gsap-anim-container {
      pointer-events: none;
    }
  `;

  document.head.appendChild(styleEl);
};

// Initialize styles on load
if (typeof document !== 'undefined') {
  addAnimationStyles();
}

/**
 * Main function to animate all content
 */
export const animateAllContent = () => {
  // Add styles
  if (typeof document !== 'undefined') {
    addAnimationStyles();
  }

  // Clear any existing animations to prevent conflicts
  clearAllAnimations();

  // Animate main content
  const mainContent = document.querySelector('.main-content');
  if (mainContent) {
    // Quick fade-in for the container
    gsap.fromTo(mainContent, 
      { opacity: 0.8 },
      { 
        opacity: 1, 
        duration: 0.3, 
        ease: "power1.out",
        onComplete: () => {
          // Animate text right after container appears
          animateTextInContainer(mainContent, {
            staggerRange: [0.01, 0.12], // Wider stagger range
            excludeSelectors: ['.alien-title', '.no-animate', 'button', 'input']
          });
        }
      }
    );
  }

  // Quick fade-in for category containers
  const categoryContainers = document.querySelectorAll('.categories, .subcategories, .category-links');
  if (categoryContainers.length) {
    gsap.fromTo(categoryContainers, 
      { opacity: 0, y: 5 },
      { 
        opacity: 1, 
        y: 0, 
        duration: 0.3,
        ease: "power1.out",
        stagger: 0.1
      }
    );
  }

  // Simple fade-in for category items
  const categoryItems = document.querySelectorAll('.category-item');
  if (categoryItems.length) {
    // Sort category items by vertical position for a top-to-bottom animation
    const sortedItems = Array.from(categoryItems).sort((a, b) => {
      const rectA = a.getBoundingClientRect();
      const rectB = b.getBoundingClientRect();

      // If items are on the same line (within a small threshold)
      if (Math.abs(rectA.top - rectB.top) < 5) {
        // Sort by horizontal position for items on the same line
        return rectA.left - rectB.left;
      }

      // Otherwise sort by vertical position
      return rectA.top - rectB.top;
    });

    // Group items by visual rows
    const rowGroups = [];
    let currentRowTop = -1;
    let currentRowGroup = [];

    sortedItems.forEach(item => {
      const rect = item.getBoundingClientRect();

      // If this is a new row (with some threshold for row height variations)
      if (currentRowTop === -1 || rect.top > currentRowTop + 5) {
        if (currentRowGroup.length > 0) {
          rowGroups.push(currentRowGroup);
        }
        currentRowGroup = [item];
        currentRowTop = rect.top;
      } else {
        // Same row, add to current group
        currentRowGroup.push(item);
      }
    });

    // Add the last group if it exists
    if (currentRowGroup.length > 0) {
      rowGroups.push(currentRowGroup);
    }

    // Animate rows sequentially using async/await pattern
    const animateRows = async () => {
      for (let rowIndex = 0; rowIndex < rowGroups.length; rowIndex++) {
        const rowItems = rowGroups[rowIndex];

        // Create a promise to track when this row's animation is complete
        await new Promise(resolve => {
          // Create a timeline for this row
          const rowTimeline = gsap.timeline({
            onComplete: () => resolve() // Resolve when row animation is complete
          });

          // Animate the items in this row
          rowTimeline.fromTo(rowItems, 
            { opacity: 0, y: 3 },
            { 
              opacity: 1, 
              y: 0, 
              duration: 0.2,
              stagger: 0.03,
              ease: "power1.out",
              onComplete: () => {
                // Animate text within the items
                rowItems.forEach((item, itemIndex) => {
                  const link = item.querySelector('a');
                  if (link && !animatedElements.has(link)) {
                    // Small staggered delay within the row
                    setTimeout(() => {
                      animateText(link, { 
                        staggerRange: [0.01, 0.12]
                      });
                    }, itemIndex * 30);
                  }

                  const count = item.querySelector('.count');
                  if (count && !animatedElements.has(count)) {
                    setTimeout(() => {
                      animateText(count, { 
                        staggerRange: [0.01, 0.08]
                      });
                    }, itemIndex * 30 + 50);
                  }
                });
              }
            }
          );
        });

        // Add a small delay between rows
        await new Promise(resolve => setTimeout(resolve, 100));
      }
    };

    // Start the sequential animation
    animateRows();
  }
};

